#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3A step 5: ciphertext codec and Encaps prep
#
# Two things land here, both prerequisites for the Encaps sequencer:
#
#   1. codec_ct, the ciphertext compression codec. Compress_d + ByteEncode_d
#      and the inverse, at d=10 for u (c1) and d=4 for v (c2). Verified
#      standalone so a packing error cannot surface later as "the ciphertext
#      is wrong" after the whole datapath has run.
#
#   2. poly_mem widened from 19 to 27 slots, with dedicated Encaps storage
#      (E1, E2, YH, MU). KeyGen slot indices 0..18 are unchanged.
#
# NOTE ON THE POLYMEM SIGNATURE: it changes from
#   checks=295 sig=9b8ffd66333f08f7  to  checks=303 sig=931534125bbcd13f
# This is NOT a regression. tb_poly_mem loops over 0 to C_SLOTS-1, so the
# wider memory means eight more slots are checked. A 19-slot build still
# reproduces the old signature exactly; the RTL behaviour is unchanged, the
# test simply covers more. KEYGEN, DATAPATH and CODEC12 are bit-identical.
#
# The Encaps checkpoint vectors EP1..EP5 are also generated here. EP4 and EP5
# are the pair that matters: lifting both basemul operands leaves u correct
# and corrupts only v, so a checkpoint on u alone would pass while the
# ciphertext is wrong.
#
# Requires all earlier Layer 3A deliveries.
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected final line: PQC L3A KEYGEN PASS vectors=4 sig=c268044aef8e69c0
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif" "$DEST/doc"
  for f in rtl/kem_keygen.vhd rtl/byte_mem.vhd rtl/pqc_round_pkg.vhd \
           verif/tb_keygen.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/codec_ct.vhd" << 'B64EOF'
LS0gPT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09
PT09PT09PT09PT09PT09PT09PT09PT0KLS0gSEVSQ09TU05VWCBQUUMgSVAgQ29yZSAtIExheWVy
IDNBCi0tIGNvZGVjX2N0OiBjaXBoZXJ0ZXh0IGNvbXByZXNzaW9uIGNvZGVjIGZvciBNTC1LRU0t
